const synthetics = require("Synthetics");
const log = require("SyntheticsLogger");

// デプロイ先のドメインは CDK スタックの環境變數 SITE_DOMAIN_NAME から渡す。
// 未設定の場合は本番ドメインへフォールバックする。
const SITE_DOMAIN_NAME = process.env.SITE_DOMAIN_NAME || "martian-imperial-year-table.c4se.jp";
const TARGET_URL = `https://${SITE_DOMAIN_NAME}/transform`;

// グレゴリオ曆側の入力欄 (年, 月, 日, 時, 分, 秒, タイムゾーン) に順番に入力する値。
const GREGORIAN_INPUT_VALUES = ["2026", "01", "01", "00", "00", "00", "+09:00"];

const EXPECTED_MARTIAN_ISO = "1428-17-28T07:04:27+00:00";
const EXPECTED_GREGORIAN_ISO = "2026-01-01T00:00:00+09:00";

const transformCheckBlueprint = async function () {
  const page = await synthetics.getPage();

  await synthetics.executeStep("navigateToTransform", async function () {
    const response = await page.goto(TARGET_URL, {
      waitUntil: "domcontentloaded",
      timeout: 30000,
    });

    if (!response) {
      throw new Error("ページの讀み込みに失敗しました。");
    }
    if (response.status() !== 200) {
      throw new Error(`ページの讀み込みに失敗しました。status=${response.status()}`);
    }

    // SPA の React ハイドレーションが完了する前に入力を始めると onChange が
    // 反映されないため、變換フォームが2つ (グレゴリオ曆・帝國火星曆) とも
    // DOM に現れるまで待つ。GA や Mackerel など第三者通信の遲延に監視結果が
    // 左右されないよう、networkidle は使はず DOM の狀態だけで判定する。
    await page.waitForFunction(() => document.querySelectorAll("form.transform-form").length >= 2, {
      timeout: 15000,
    });
  });

  await synthetics.executeStep("inputGregorianDate", async function () {
    // 變換フォームは1つ目がグレゴリオ曆、2つ目が帝國火星曆。
    const forms = await page.$$("form.transform-form");
    if (forms.length < 2) {
      throw new Error(`變換フォームが見つかりませんでした。forms.length=${forms.length}`);
    }

    const gregorianInputs = await forms[0].$$("input");
    if (gregorianInputs.length < GREGORIAN_INPUT_VALUES.length) {
      throw new Error(`グレゴリオ曆の入力欄が不足しています。inputs.length=${gregorianInputs.length}`);
    }

    // React の制禦下にある number/text input は value の直接書き換へでは
    // onChange が發火しないため、實際のクリック + キー入力で狀態を更新する。
    // click({clickCount: 3}) や el.select() は type="number" ではテキスト選擇
    // API をサポートせず例外または no-op になり、既存値 (讀込時點の現在時刻)
    // の後ろに追記されてしまふため、キーボードの Ctrl+A で全選擇してから入力する。
    for (let i = 0; i < GREGORIAN_INPUT_VALUES.length; i++) {
      const input = gregorianInputs[i];
      await input.click();
      await page.keyboard.down("Control");
      await page.keyboard.press("KeyA");
      await page.keyboard.up("Control");
      await input.type(GREGORIAN_INPUT_VALUES[i], { delay: 20 });

      const actualValue = await input.evaluate((el) => el.value);
      if (actualValue !== GREGORIAN_INPUT_VALUES[i]) {
        throw new Error(
          `入力欄 (index=${i}) への入力に失敗しました。expected="${GREGORIAN_INPUT_VALUES[i]}" actual="${actualValue}"`,
        );
      }
    }

    await page.keyboard.press("Tab");

    // 入力が實際に State へ反映され、グレゴリオ曆側の表示が期待値と
    // 一致することを確認する。ここで一致しなければ「入力が效かなかった」
    // ことが原因であり、Martian 側の變換結果の問題ではないと切り分けられる。
    await page.waitForFunction(
      (expected) => {
        const forms = document.querySelectorAll("form.transform-form");
        if (forms.length < 2) return false;
        const box = forms[0].closest(".box");
        const code = box ? box.querySelector("code") : null;
        return !!code && code.textContent.trim() === expected;
      },
      { timeout: 10000 },
      EXPECTED_GREGORIAN_ISO,
    );
  });

  await synthetics.executeStep("verifyMartianDate", async function () {
    await page.waitForFunction(
      (expected) => {
        const forms = document.querySelectorAll("form.transform-form");
        if (forms.length < 2) return false;
        const box = forms[1].closest(".box");
        const code = box ? box.querySelector("code") : null;
        return !!code && code.textContent.trim() === expected;
      },
      { timeout: 15000 },
      EXPECTED_MARTIAN_ISO,
    );

    const resultText = await page.evaluate(() => {
      const forms = document.querySelectorAll("form.transform-form");
      const box = forms[1].closest(".box");
      const code = box ? box.querySelector("code") : null;
      return code ? code.textContent.trim() : null;
    });

    log.info(`帝國火星曆の變換結果: ${resultText}`);

    await synthetics.takeScreenshot("result", "loaded");

    if (resultText !== EXPECTED_MARTIAN_ISO) {
      throw new Error(`變換結果が期待値と異なります。expected="${EXPECTED_MARTIAN_ISO}" actual="${resultText}"`);
    }
  });
};

exports.handler = async () => {
  const failures = [];
  for (const [name, check] of [
    ["transform", transformCheckBlueprint],
    ["calendar", checkCalendar],
    ["restApi", checkRestApi],
    ["mcp", checkMcp],
    ["graphql", checkGraphql],
  ]) {
    try {
      await synthetics.executeStep(name, check);
    } catch (error) {
      const message = `${name}: ${error instanceof Error ? error.message : String(error)}`;
      failures.push(message);
      log.error(message);
    }
  }
  if (failures.length) throw new Error(`監視失敗: ${failures.join("; ")}`);
};

async function checkCalendar() {
  const page = await synthetics.getPage();
  const response = await page.goto(`https://${SITE_DOMAIN_NAME}/calendar`, {
    waitUntil: "domcontentloaded",
    timeout: 30000,
  });
  if (!response || response.status() !== 200) {
    throw new Error(`七曜表の讀み込み失敗: status=${response ? response.status() : "no response"}`);
  }
  await page.waitForSelector(".calendar-svg-wrapper svg title", { timeout: 30000 });
  const inputs = await page.$$(".calendar-form input");
  if (inputs.length !== 3) throw new Error(`七曜表の入力欄が不正です: ${inputs.length}`);
  for (const [index, value] of ["1428", "17", "+09:00"].entries()) {
    await inputs[index].click();
    await page.keyboard.down("Control");
    await page.keyboard.press("KeyA");
    await page.keyboard.up("Control");
    await inputs[index].type(value, { delay: 20 });
  }
  await page.click('.calendar-form button[type="submit"]');
  await verifyCalendar(page, 1428, 17);
  await clickCalendarButton(page, "次の月");
  await verifyCalendar(page, 1428, 18);
  await clickCalendarButton(page, "前の月");
  await verifyCalendar(page, 1428, 17);
  const download = await page.$eval('a[download="calendar-1428-17.svg"]', (link) => link.getAttribute("href"));
  if (!download || !download.startsWith("data:image/svg+xml")) throw new Error("SVG ダウンロードが不正です");
  const svg = decodeURIComponent(download.slice(download.indexOf(",") + 1));
  if (!svg.includes("帝國火星曆1428年17月")) throw new Error("ダウンロード SVG の年月が不正です");
  await synthetics.takeScreenshot("calendar", "loaded");
}

async function verifyCalendar(page, year, month) {
  await page.waitForFunction(
    (expected) => {
      const title = document.querySelector(".calendar-svg-wrapper svg title");
      return title && title.textContent === expected && !document.querySelector("progress");
    },
    { timeout: 30000 },
    `帝國火星曆${year}年${month}月`,
  );
}

async function clickCalendarButton(page, text) {
  const clicked = await page.evaluate((label) => {
    const button = [...document.querySelectorAll("button")].find((item) => item.textContent.trim() === label);
    if (!button || button.disabled) return false;
    button.click();
    return true;
  }, text);
  if (!clicked) throw new Error(`七曜表のボタンを押せません: ${text}`);
}

async function post(path, body, accept = "application/json") {
  const response = await fetch(`https://${SITE_DOMAIN_NAME}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: accept },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(15000),
  });
  if (response.status !== 200) throw new Error(`${path}: HTTP ${response.status}`);
  return response.text();
}

function parseJson(text, label) {
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(`${label}: JSON を解析できません`);
  }
}

function verifyResult(value, label) {
  if (value !== EXPECTED_MARTIAN_ISO) {
    throw new Error(`${label}: expected=${EXPECTED_MARTIAN_ISO} actual=${String(value)}`);
  }
}

async function checkRestApi() {
  const body = parseJson(await post("/api/imperial-datetime/from-gregorian", {
    gregorianDateTime: EXPECTED_GREGORIAN_ISO,
    imperialTimezone: "+00:00",
  }), "REST");
  verifyResult(body?.imperialDateTimeFormatted, "REST");
}

async function checkMcp() {
  const text = await post("/mcp", {
    jsonrpc: "2.0",
    id: 1,
    method: "tools/call",
    params: {
      name: "convert_gregorian_to_imperial_datetime",
      arguments: { gregorianDateTime: EXPECTED_GREGORIAN_ISO, imperialTimezone: "+00:00" },
    },
  }, "application/json, text/event-stream");
  const data = text.split(/\r?\n/).filter((line) => line.startsWith("data:"))
    .map((line) => line.slice(5).trimStart()).join("\n");
  if (!data) throw new Error("MCP: SSE データがありません");
  const body = parseJson(data, "MCP");
  if (body?.jsonrpc !== "2.0" || body.id !== 1 || body.error || !body.result || body.result.isError) {
    throw new Error(`MCP: JSON-RPC エラーまたは不正な結果: ${JSON.stringify(body)}`);
  }
  verifyResult(body.result.structuredContent?.response?.imperialDateTimeFormatted, "MCP");
}

async function checkGraphql() {
  const body = parseJson(await post("/graphql", {
    query: 'query Convert($date: GregorianDateTimeString!) { fromGregorian(datetime: $date) { imperial(timezone: "+00:00") { formatted } } }',
    variables: { date: EXPECTED_GREGORIAN_ISO },
  }), "GraphQL");
  if (body?.errors?.length) throw new Error(`GraphQL: ${JSON.stringify(body.errors)}`);
  verifyResult(body?.data?.fromGregorian?.imperial?.formatted, "GraphQL");
}
